/**
 * Art looked up from the Vite asset graph.
 *
 * Both folders are generated by tools/fetch_hero_art.py:
 *  - banner: the in-game TFT champion banner (pool, hex board, spotlight)
 *  - wallpaper: the square set splash (only the blurred global backdrop)
 */
const bannerModules = import.meta.glob('../assets/heroes/banner/*.webp', {
  eager: true,
  query: '?url',
  import: 'default',
}) as Record<string, string>;

const wallpaperModules = import.meta.glob('../assets/heroes/wallpaper/*.webp', {
  eager: true,
  query: '?url',
  import: 'default',
}) as Record<string, string>;

const stageModules = import.meta.glob('../assets/board/*.webp', {
  eager: true,
  query: '?url',
  import: 'default',
}) as Record<string, string>;

/**
 * assets/fx holds the client's new-item halo clip (see the lol-client-ui-effects
 * skill). It is a video, so it stays out of the portrait lookup tables.
 */
const fxModules = import.meta.glob('../assets/fx/*.webm', {
  eager: true,
  query: '?url',
  import: 'default',
}) as Record<string, string>;

function index(modules: Record<string, string>): Map<string, string> {
  const map = new Map<string, string>();
  for (const [path, url] of Object.entries(modules)) {
    const name = path.split('/').pop()?.replace(/\.webp$/, '');
    if (name) map.set(name, url);
  }
  return map;
}

const banners = index(bannerModules);
const wallpapers = index(wallpaperModules);
const stageUrl =
  Object.entries(stageModules).find(([path]) => path.endsWith('/stage.webp'))?.[1] ?? '';

export function heroBanner(art: string): string | null {
  return banners.get(art) ?? null;
}

export function heroWallpaper(art: string): string | null {
  return wallpapers.get(art) ?? banners.get(art) ?? null;
}

export function boardStage(): string {
  return stageUrl;
}

export function heroArtCount(): number {
  return banners.size;
}

/** Empty when the clip is absent, which disables the halo instead of breaking it. */
export function lingerGlow(): string {
  return Object.entries(fxModules).find(([path]) => path.includes('linger'))?.[1] ?? '';
}
